-- OpsCore enterprise-value additions. All objects are tenant-scoped.
CREATE TABLE IF NOT EXISTS approval_requests (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, entity_type text NOT NULL, entity_id TEXT NOT NULL, action text NOT NULL, reason text NOT NULL, status text NOT NULL CHECK(status IN ('pending','approved','rejected','cancelled')), requested_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, decided_by TEXT REFERENCES users(id) ON DELETE SET NULL, decision_reason text, created_at timestamptz NOT NULL DEFAULT now(), decided_at timestamptz);
CREATE UNIQUE INDEX IF NOT EXISTS uq_approval_pending ON approval_requests(organization_id,entity_type,entity_id,action,status);
CREATE INDEX IF NOT EXISTS idx_approval_org_status ON approval_requests(organization_id,status,created_at);
CREATE TABLE IF NOT EXISTS inventory_ledger (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, part_id TEXT NOT NULL REFERENCES parts(id) ON DELETE RESTRICT, location_id TEXT NOT NULL REFERENCES inventory_locations(id) ON DELETE RESTRICT, work_order_id TEXT REFERENCES work_orders(id) ON DELETE SET NULL, source_type text NOT NULL, source_id text, quantity_delta integer NOT NULL, balance_after integer NOT NULL CHECK(balance_after >= 0), reason text NOT NULL, actor_user_id TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_inventory_ledger_org_part ON inventory_ledger(organization_id,part_id,location_id,created_at);
CREATE TABLE IF NOT EXISTS business_calendars (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, name text NOT NULL, timezone text NOT NULL, week_json jsonb NOT NULL, active boolean NOT NULL DEFAULT true, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE UNIQUE INDEX IF NOT EXISTS uq_business_calendar_name ON business_calendars(organization_id,name);
CREATE TABLE IF NOT EXISTS business_calendar_exceptions (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, calendar_id TEXT NOT NULL REFERENCES business_calendars(id) ON DELETE CASCADE, date date NOT NULL, is_working boolean NOT NULL, start_minutes integer, end_minutes integer, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(calendar_id,date));
CREATE TABLE IF NOT EXISTS work_order_bulk_jobs (id TEXT PRIMARY KEY DEFAULT gen_random_uuid()::text::text, organization_id TEXT NOT NULL REFERENCES organizations(id) ON DELETE CASCADE, operation text NOT NULL, requested_count integer NOT NULL, affected_count integer NOT NULL DEFAULT 0, status text NOT NULL CHECK(status IN ('completed','partial','failed')), request_hash text NOT NULL, result_json jsonb NOT NULL, created_by TEXT NOT NULL REFERENCES users(id) ON DELETE RESTRICT, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS idx_bulk_jobs_org_created ON work_order_bulk_jobs(organization_id,created_at);
